// Supervisor busy-port test repair check (run inside the Dev Container from the repo root).
// A: time scripts/dev.mjs with port 3001 occupied: build phase until the API reports its busy port, then cleanup until close.
// B/C: with a stub `pnpm` that always exits 1 (a failed build), the previous test version passes and the repaired one fails.
// D: the repaired test passes normally.
import { spawn, spawnSync, execFileSync } from 'node:child_process';
import { once } from 'node:events';
import { createServer } from 'node:http';
import { mkdtempSync, writeFileSync, chmodSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const out = {};
{
  const server = createServer((_q, r) => r.end('existing-listener')); await new Promise(r => server.listen(3001, '0.0.0.0', r));
  const t0 = performance.now(); let marker;
  const child = spawn(process.execPath, ['scripts/dev.mjs'], { env: { PATH: process.env.PATH, HOME: process.env.HOME, APP_ENV: 'local' }, stdio: ['ignore', 'pipe', 'pipe'] });
  let text = ''; const collect = c => { text = (text + c).slice(-65536); if (marker === undefined && text.includes('api foundation startup failed')) marker = performance.now(); };
  child.stdout.on('data', collect); child.stderr.on('data', collect);
  const [code, signal] = await once(child, 'close'); const end = performance.now();
  out.A_measured = { exit: [code, signal], buildAndStartMs: Math.round(marker - t0), cleanupAfterApiFailureMs: Math.round(end - marker), totalMs: Math.round(end - t0) };
  await new Promise(r => server.close(r));
}
const dir = mkdtempSync(join(tmpdir(), 'audit-stub-pnpm-')), old = join(dir, 'previous-processes.test.mjs');
try {
  writeFileSync(join(dir, 'pnpm'), '#!/bin/sh\necho "stub build failure" >&2\nexit 1\n'); chmodSync(join(dir, 'pnpm'), 0o755);
  writeFileSync(old, execFileSync('git', ['show', '5347cc0:tests/foundation/processes.test.mjs']));
  const run = (file, path) => { const r = spawnSync(process.execPath, ['--test', '--test-reporter=tap', '--test-name-pattern=development supervisor', file], { env: { ...process.env, PATH: path }, encoding: 'utf8' });
    return { exit: r.status, pass: Number((r.stdout.match(/^# pass (\d+)/m) || [])[1]), fail: Number((r.stdout.match(/^# fail (\d+)/m) || [])[1]), message: (r.stdout.match(/API did not report its busy port/) || [null])[0] }; };
  out.B_previousTestWithFailedBuild = run(old, dir + ':' + process.env.PATH);
  out.C_repairedTestWithFailedBuild = run('tests/foundation/processes.test.mjs', dir + ':' + process.env.PATH);
  out.D_repairedTestNormal = run('tests/foundation/processes.test.mjs', process.env.PATH);
} finally { rmSync(dir, { recursive: true, force: true }); }
console.log(JSON.stringify(out, null, 1));
const ok = out.A_measured.exit[0] === 1 && out.B_previousTestWithFailedBuild.exit === 0 && out.C_repairedTestWithFailedBuild.exit !== 0 && out.C_repairedTestWithFailedBuild.message && out.D_repairedTestNormal.exit === 0 && out.D_repairedTestNormal.pass === 1;
if (!ok) process.exitCode = 1;
